-- Food Uncle ecosystem v2
-- Applied to Supabase project dibnupnkpqlqkriqcczg.
create table if not exists public.order_status_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, status text not null, note text, actor_id uuid references auth.users(id), created_at timestamptz not null default now());
create index if not exists order_status_history_order_idx on public.order_status_history(order_id, created_at desc);
create table if not exists public.delivery_assignments (id uuid primary key default gen_random_uuid(), order_id uuid not null unique references public.orders(id) on delete cascade, delivery_boy_id uuid references public.profiles(id), status text not null default 'assigned' check (status in ('assigned','accepted','picked_up','out_for_delivery','delivered','cancelled')), assigned_at timestamptz not null default now(), accepted_at timestamptz, picked_up_at timestamptz, delivered_at timestamptz, payment_received boolean not null default false, note text);
create index if not exists delivery_assignments_driver_idx on public.delivery_assignments(delivery_boy_id,status);
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, order_id uuid references public.orders(id) on delete cascade, title text not null, message text not null, kind text not null default 'order', is_read boolean not null default false, created_at timestamptz not null default now());
create index if not exists notifications_user_idx on public.notifications(user_id,is_read,created_at desc);
create table if not exists public.restaurant_staff (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('owner','manager','delivery_boy')), active boolean not null default true, created_at timestamptz not null default now(), unique(user_id,role));
alter table public.orders alter column customer_id drop not null;
create or replace function public.place_order(p_customer_name text,p_customer_phone text,p_order_type text,p_table_number text,p_delivery_address text,p_instructions text,p_payment_method text,p_items jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_order_id uuid; v_order_number bigint; v_subtotal numeric:=0; v_tax numeric:=0; v_delivery_fee numeric:=0; v_total numeric:=0; v_item jsonb; v_menu public.menu_items%rowtype; v_qty int; v_unit numeric; v_settings public.restaurant_settings%rowtype; v_user uuid:=auth.uid(); begin if coalesce(trim(p_customer_name),'')='' then raise exception 'Customer name is required'; end if; if p_order_type not in ('delivery','table','dine_in','takeaway') then raise exception 'Invalid order type'; end if; if p_payment_method not in ('cod','pay_at_counter','online') then raise exception 'Invalid payment method'; end if; if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Cart is empty'; end if; select * into v_settings from public.restaurant_settings where id=1; for v_item in select * from jsonb_array_elements(p_items) loop select * into v_menu from public.menu_items where id=(v_item->>'menu_item_id')::uuid and is_available=true; if not found then raise exception 'Menu item unavailable'; end if; v_qty:=greatest(1,least(20,coalesce((v_item->>'quantity')::int,1))); v_unit:=coalesce(v_menu.discount_price,v_menu.price); v_subtotal:=v_subtotal+(v_unit*v_qty); end loop; if v_subtotal<coalesce(v_settings.min_order_value,0) then raise exception 'Minimum order value is %',v_settings.min_order_value; end if; if p_order_type='delivery' then if not coalesce(v_settings.delivery_enabled,true) then raise exception 'Delivery is currently unavailable'; end if; v_delivery_fee:=case when coalesce(v_settings.free_delivery_above,0)>0 and v_subtotal>=v_settings.free_delivery_above then 0 else coalesce(v_settings.flat_delivery_fee,0) end; end if; v_tax:=round(v_subtotal*coalesce(v_settings.tax_percent,0)/100,2); v_total:=v_subtotal+v_delivery_fee+v_tax; insert into public.orders(customer_id,user_id,customer_name,customer_phone,order_type,table_number,delivery_address,instructions,status,payment_method,payment_status,total_amount,subtotal,delivery_fee,tax,total) values(v_user,v_user,p_customer_name,p_customer_phone,p_order_type,p_table_number,p_delivery_address,p_instructions,'placed',p_payment_method,'pending',v_total,v_subtotal,v_delivery_fee,v_tax,v_total) returning id,order_number into v_order_id,v_order_number; for v_item in select * from jsonb_array_elements(p_items) loop select * into v_menu from public.menu_items where id=(v_item->>'menu_item_id')::uuid and is_available=true; v_qty:=greatest(1,least(20,coalesce((v_item->>'quantity')::int,1))); v_unit:=coalesce(v_menu.discount_price,v_menu.price); insert into public.order_items(order_id,menu_item_id,item_name,quantity,unit_price,line_total,addons,notes) values(v_order_id,v_menu.id,v_menu.name,v_qty,v_unit,v_unit*v_qty,coalesce(v_item->'addons','[]'::jsonb),null); end loop; insert into public.order_status_history(order_id,status,note) values(v_order_id,'placed','Order received'); return jsonb_build_object('id',v_order_id,'order_number',v_order_number,'subtotal',v_subtotal,'delivery_fee',v_delivery_fee,'tax',v_tax,'total',v_total,'status','placed'); end; $$;
revoke all on function public.place_order(text,text,text,text,text,text,text,jsonb) from public;
grant execute on function public.place_order(text,text,text,text,text,text,text,jsonb) to anon,authenticated;
insert into public.dining_tables(table_number,is_active) values ('T1',true),('T2',true),('T3',true),('T4',true),('T5',true) on conflict(table_number) do nothing;
insert into public.categories(name,sort_order,is_active) values ('Bestsellers',1,true),('Burgers',2,true),('Pizza',3,true),('Indian',4,true),('Drinks',5,true),('Desserts',6,true) on conflict(name) do update set sort_order=excluded.sort_order,is_active=true;
insert into public.menu_items(name,description,price,discount_price,category_id,is_available,is_bestseller,is_recommended,is_veg,prep_time_minutes,keywords) select * from (values ('Classic Chicken Burger','Crispy chicken, lettuce, house sauce',179::numeric,159::numeric,(select id from categories where name='Burgers'),true,true,true,false,12,'burger,chicken,crispy'),('Paneer Tikka Pizza','Smoky paneer, peppers, onion and cheese',299::numeric,269::numeric,(select id from categories where name='Pizza'),true,true,true,true,18,'pizza,paneer,veg'),('Butter Chicken Bowl','Creamy butter chicken with rice and naan',289::numeric,null,(select id from categories where name='Indian'),true,false,true,false,20,'chicken,indian,rice'),('Masala Chai','Classic Indian spiced tea',69::numeric,null,(select id from categories where name='Drinks'),true,true,true,true,6,'tea,chai,hot'),('Cold Coffee','Chilled coffee with creamy foam',119::numeric,99::numeric,(select id from categories where name='Drinks'),true,false,true,true,5,'coffee,cold'),('Chocolate Brownie','Warm chocolate brownie',129::numeric,null,(select id from categories where name='Desserts'),true,false,true,true,8,'brownie,chocolate')) as x(name,description,price,discount_price,category_id,is_available,is_bestseller,is_recommended,is_veg,prep_time_minutes,keywords) where not exists(select 1 from public.menu_items m where m.name=x.name);
